func load(done: (Int) -> Void) {
    done(42)
}
load { print($0) }

func old(_ f: @escaping (Int) -> Void) { f(42) }
func modern() async -> Int {
    await withCheckedContinuation { c in
        old { c.resume(returning: $0) } }
}
print(await modern())

func get(_ ok: Bool) async -> String {
    await withCheckedContinuation { c in
        if ok { c.resume(returning: "yes") }
        else { c.resume(returning: "no") } }
}
print(await get(true))

